import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"LLMs.txt","description":"","frontmatter":{},"headers":[],"relativePath":"ai/llms.md","filePath":"ai/llms.md","lastUpdated":1792596226000}`),a={name:`ai/llms.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="llms-txt" tabindex="-1">LLMs.txt <a class="header-anchor" href="#llms-txt" aria-label="Permalink to “LLMs.txt”">​</a></h1><p>文档站在构建时产出一组给大语言模型读的机读资产，内容与站点正文同源。AI 工具读取它们即可了解打印设计器的模板结构、元素、API 与用法。</p><h2 id="可用资源" tabindex="-1">可用资源 <a class="header-anchor" href="#可用资源" aria-label="Permalink to “可用资源”">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://print.docs.xihanfun.com/llms.txt" target="_blank" rel="noreferrer">llms.txt</a></td><td>索引：全部页面的标题、一句话摘要与地址，以及下列资产的入口</td></tr><tr><td><a href="https://print.docs.xihanfun.com/llms-full.txt" target="_blank" rel="noreferrer">llms-full.txt</a></td><td>全站正文，正文引用的示例代码已内联</td></tr><tr><td><a href="https://print.docs.xihanfun.com/llms-guide.txt" target="_blank" rel="noreferrer">llms-guide.txt</a></td><td>指南：模板结构、数据绑定与格式化、富文本、运行时、设计器、打印客户端、与宿主集成</td></tr><tr><td><a href="https://print.docs.xihanfun.com/llms-reference.txt" target="_blank" rel="noreferrer">llms-reference.txt</a></td><td>参考：元素、模板类型、问题码与诊断，以及预览与打印、设计器、打印客户端 SDK、模型层 core 的 API</td></tr></tbody></table><p><strong>单页 Markdown</strong>：任何一页的站点地址后加 <code>.md</code> 即可取到这一页的 Markdown，如 <a href="https://print.docs.xihanfun.com/guide/template.md" target="_blank" rel="noreferrer">guide/template.md</a>、<a href="https://print.docs.xihanfun.com/reference/elements.md" target="_blank" rel="noreferrer">reference/elements.md</a>。每页正文上方的「取本页 Markdown」也指向它。</p><p><code>llms-full.txt</code> 体积较大，多数场景读 <code>llms.txt</code> 索引后按需取单页，或只取 <code>llms-guide.txt</code>、<code>llms-reference.txt</code> 之一。</p><p>站点在发版时部署，这些资产对应 npm 上最新发布的版本。打印用到 XiHan.UI 的样式、设计器零件与语言包，UI 的机读资产见 <a href="https://ui.docs.xihanfun.com/llms.txt" target="_blank" rel="noreferrer">ui.docs.xihanfun.com/llms.txt</a>。</p><h2 id="在-ai-工具中使用" tabindex="-1">在 AI 工具中使用 <a class="header-anchor" href="#在-ai-工具中使用" aria-label="Permalink to “在 AI 工具中使用”">​</a></h2><p>所有工具都可以用同一段提示词：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>阅读 https://print.docs.xihanfun.com/llms.txt 了解曦寒打印设计器，写打印相关的代码时按需读取其中列出的页面（站点地址后加 .md 取 Markdown），以文档为准，不要凭记忆写元素、属性与模板结构；用到 XiHan.UI 时再读 https://ui.docs.xihanfun.com/llms.txt。</span></span></code></pre></div><table tabindex="0"><thead><tr><th>工具</th><th>做法</th></tr></thead><tbody><tr><td>Claude Code</td><td>写进项目的 <code>CLAUDE.md</code>，或用 <code>/memory</code> 记下</td></tr><tr><td>Cursor</td><td>在对话中用 <code>@Docs</code> 添加 <code>https://print.docs.xihanfun.com/llms.txt</code>，或写进 <code>.cursor/rules</code></td></tr><tr><td>Codex</td><td>写进项目的 <code>AGENTS.md</code></td></tr><tr><td>GitHub Copilot</td><td>写进 <code>.github/copilot-instructions.md</code></td></tr><tr><td>Windsurf</td><td>写进 <code>.windsurf/rules</code></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./agents">For Agents</a></li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};